#!/usr/bin/env node
'use strict'

const fs = require('fs')
const path = require('path')

const root = path.resolve(__dirname, '..')
const sourcePath = path.join(root, 'shared', 'identifierCatalog.json')
const outputPath = path.join(root, 'sql', 'stable-identifiers', '002_catalog_seed.generated.sql')
const catalog = JSON.parse(fs.readFileSync(sourcePath, 'utf8'))

const q = value => `'${String(value ?? '').replaceAll("'", "''")}'`
const nullable = value => value == null ? 'null' : q(value)
const bool = value => value === true ? 'true' : 'false'
const lines = [
  '-- GENERATED by scripts/generate-identifier-seed.js. Do not hand-edit.',
  `-- Catalog version: ${catalog.catalogVersion}`,
  '-- Additive and idempotent: existing labels and semantic settings are preserved.',
  '',
  'begin;',
  '',
]

for (const workflow of catalog.workflows || []) {
  lines.push(
    'insert into public.workflow_definitions(code, entity_type_code, label)',
    `select ${q(workflow.code)}, ${q(workflow.entityTypeCode)}, ${q(workflow.label)}`,
    `where not exists (select 1 from public.workflow_definitions where organization_id is null and code = ${q(workflow.code)});`,
    ''
  )
  for (const [index, state] of (workflow.states || []).entries()) {
    lines.push(
      'insert into public.workflow_states(',
      '  workflow_id, code, label, legacy_storage_value, color, sort_order, semantic_type,',
      '  is_initial, is_terminal, counts_as_active, counts_as_won',
      ')',
      `select w.id, ${q(state.code)}, ${q(state.label)}, ${q(state.storageValue || state.legacyValues?.[0] || state.code)}, ${nullable(state.color)}, ${index}, ${q(state.semanticType || 'open')},`,
      `  ${bool(state.isInitial)}, ${bool(state.isTerminal)}, ${bool(state.countsAsActive)}, ${bool(state.countsAsWon)}`,
      'from public.workflow_definitions w',
      `where w.organization_id is null and w.code = ${q(workflow.code)}`,
      `  and not exists (select 1 from public.workflow_states s where s.workflow_id = w.id and s.code = ${q(state.code)});`,
      ''
    )
    for (const alias of state.legacyValues || []) {
      lines.push(
        'insert into public.workflow_state_aliases(workflow_state_id, alias, source_code)',
        `select s.id, ${q(alias)}, 'legacy'`,
        'from public.workflow_states s',
        'join public.workflow_definitions w on w.id = s.workflow_id',
        `where w.organization_id is null and w.code = ${q(workflow.code)} and s.code = ${q(state.code)}`,
        `  and not exists (select 1 from public.workflow_state_aliases a where a.workflow_state_id = s.id and a.source_code = 'legacy' and lower(btrim(a.alias)) = lower(btrim(${q(alias)})));`,
        ''
      )
    }
  }
}

for (const choiceSet of catalog.choiceSets || []) {
  lines.push(
    'insert into public.choice_sets(code, label)',
    `select ${q(choiceSet.code)}, ${q(choiceSet.label)}`,
    `where not exists (select 1 from public.choice_sets where organization_id is null and code = ${q(choiceSet.code)});`,
    ''
  )
  for (const [index, option] of (choiceSet.options || []).entries()) {
    lines.push(
      'insert into public.choice_options(choice_set_id, code, label, legacy_storage_value, color, sort_order)',
      `select c.id, ${q(option.code)}, ${q(option.label)}, ${q(option.storageValue || option.legacyValues?.[0] || option.code)}, ${nullable(option.color)}, ${index}`,
      'from public.choice_sets c',
      `where c.organization_id is null and c.code = ${q(choiceSet.code)}`,
      `  and not exists (select 1 from public.choice_options o where o.choice_set_id = c.id and o.code = ${q(option.code)});`,
      ''
    )
    for (const alias of option.legacyValues || []) {
      lines.push(
        'insert into public.choice_option_aliases(choice_option_id, alias, source_code)',
        `select o.id, ${q(alias)}, 'legacy'`,
        'from public.choice_options o',
        'join public.choice_sets c on c.id = o.choice_set_id',
        `where c.organization_id is null and c.code = ${q(choiceSet.code)} and o.code = ${q(option.code)}`,
        `  and not exists (select 1 from public.choice_option_aliases a where a.choice_option_id = o.id and a.source_code = 'legacy' and lower(btrim(a.alias)) = lower(btrim(${q(alias)})));`,
        ''
      )
    }
  }
}

for (const role of catalog.roles || []) {
  lines.push(
    'insert into public.role_definitions(code, label)',
    `select ${q(role.code)}, ${q(role.label)}`,
    `where not exists (select 1 from public.role_definitions where organization_id is null and code = ${q(role.code)});`,
    ''
  )
}

for (const board of catalog.boards || []) {
  lines.push(
    'insert into public.board_definitions(code, label, entity_type_code)',
    `select ${q(board.code)}, ${q(board.label)}, ${q(board.entityTypeCode)}`,
    `where not exists (select 1 from public.board_definitions where organization_id is null and code = ${q(board.code)});`,
    ''
  )
}

lines.push('commit;', '')
fs.writeFileSync(outputPath, lines.join('\n'))
process.stdout.write(`Generated ${path.relative(root, outputPath)}\n`)
